import{z as i,x as A,o as E,c as D,q as n,j as t,D as l,d as o,s as B,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Dragonfly 与 torus 对照","description":"","frontmatter":{"title":"Dragonfly 与 torus 对照","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dragonfly-torus.md","filePath":"llm/dragonfly-torus.md","lastUpdated":1791063341000}'),d={name:"llm/dragonfly-torus.md"};function p(f,a,g,m,u,C){const e=A("Mermaid");return E(),D("div",null,[a[2]||(a[2]=n('<h1 id="dragonfly-与-torus-对照" tabindex="-1">Dragonfly 与 torus 对照 <a class="header-anchor" href="#dragonfly-与-torus-对照" aria-label="Permalink to &quot;Dragonfly 与 torus 对照&quot;">​</a></h1><div class="epigraph"><p>脂肪树用分层交换机堆端口；Dragonfly 用组间少量长边换直径；环面用规则网格换可预测的邻居。三种图都能跑 NCCL，局部性假设完全不同。</p><footer>—— Dragonfly 见 Kim 等 SC 2008；环面见 Blue Gene / Cray 一类 HPC 系统；脂肪树对照 Clos 课</footer></div><p><a href="/llm/rail-optimized-topology">上一课</a> 把 GPU 训练网默认画成轨优化脂肪树。本课补对照：HPC 里更常见的 <strong>Dragonfly</strong> 与 <strong>torus（环面）</strong> 仍会出现在部分训练集群与超算上。缺口不是再讲 Clos，而是：集合通信的环邻居、树根、All-to-All 置换，在这三种图上分别踩中什么边。后课拥塞控制会用到「热点在组间链路还是在网格边上」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>脂肪树的优点是路径多样、扩展以加脊柱为主，缺点是跳数随层数涨、布线与交换机台数贵。Dragonfly 把端点收成组，组内高带宽，组间少量光学长边；直径小，长边贵且容易成为全局热点。环面（2D/3D torus）每节点度固定，只与网格邻居相连，扩展时直径涨，但布线规则、本地集体很便宜。</p><p><span class="marginnote">「直径」是图里最远两点的最少跳数，可以想成「最偏的两个组要握一次手，中间至少经过几根线」：Dragonfly 用组内一跳加长边一跳把它压到两三跳，环面则随网格边长往上涨。直径小意味着任何两端的对话都不必穿过太多交换机。</span></p><p>若把轨优化那套「同号 GPU 走同一平面」搬到 Dragonfly，组间长边没有「轨」这个编号；All-Reduce 的逻辑环若把逻辑邻居放在不同组，每一步都走长边，\\(\\alpha\\) 与争用一起爆。若把环面当成 NVLink 域，会高估非邻居对的带宽——网格上最远一对要多跳转发。问题是：<strong>并行网格的局部性必须匹配图的局部性</strong>，不能只匹配卡数。</p><p><span class="marginnote">Kim 等人提出 Dragonfly 是为了用光学长边降低直径，同时保持组内电互联便宜。后续 Cray / HPE 系统做过产品化。本课不填写未公开的某超算端口表，只对照结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三件事：直径、最小割、集体算法该用哪张调度图。</p><p>脂肪树 / 轨优化：DP 沿轨，TP 在节点内，All-to-All 怕叶子上行。Dragonfly：尽量让高频集体（TP、节点内 EP）停在组内；跨组只走 DP 或低频。组间 All-to-All 会打满长边，需要自适应路由或把 EP 度缩进组。环面：让环 All-Reduce 的逻辑环嵌在物理环上（沿一维走），避免对角跳；树可以沿维归约，类似网格上的维序路由。</p><p><span class="marginnote">「集合通信」就是一组进程同时参与的通信动作：All-Reduce 是每人都拿到全体数据的某种汇总（比如求和）。它不是两台机器的点对点传输，而是一波同步——最慢的那条链路决定全队的完成时间，所以热点边会拖住整个集群。</span></p>',12)),(E(),t(s,null,{default:l(()=>[B(e,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FT%5B%22Fat%20tree%20%2F%20rail%22%5D%20--%3E%20DP%5B%22DP%20%E6%B2%BF%E8%BD%A8%22%5D%0A%20%20DF%5B%22Dragonfly%22%5D%20--%3E%20GRP%5B%22%E7%BB%84%E5%86%85%E9%AB%98%E9%A2%91%20%2F%20%E7%BB%84%E9%97%B4%E4%BD%8E%E9%A2%91%22%5D%0A%20%20TOR%5B%22Torus%22%5D%20--%3E%20EMB%5B%22%E9%80%BB%E8%BE%91%E7%8E%AF%E5%B5%8C%E5%85%A5%E7%89%A9%E7%90%86%E7%8E%AF%22%5D%0A%20%20DF%20--%3E%20HOT%5B%22%E7%BB%84%E9%97%B4%E9%95%BF%E8%BE%B9%E7%83%AD%E7%82%B9%22%5D%0A%20%20TOR%20--%3E%20DIA%5B%22%E7%9B%B4%E5%BE%84%E9%9A%8F%E8%A7%84%E6%A8%A1%E6%B6%A8%22%5D%0A%20%20FT%20--%3E%20COST%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%E4%B8%8E%E5%B8%83%E7%BA%BF%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"NCCL 会探到的是点对点可达与带宽档，不会自动「理解 Dragonfly 组」。进程编号若按机架扫描而不是按组扫描，逻辑环会随机切长边。编号纪律与轨优化同样重要，只是对齐的单位从「GPU 号」换成「组号」或「网格坐标」。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[o("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"集合通信的同步波在 Dragonfly 长边上表现为 incast：多个组同时把归约结果打向树根所在组。自适应路由可以把流打散，但会破坏有序与 infiniband 风格的无损假设，以太网实现更常见。环面上，维序路由要靠虚拟通道拆掉环绕链路构成的环依赖才无死锁，但集体若同时占用同一维的所有边，会出现与 rail 极化类似的「一维打满」。",-1)),(E(),t(s,null,{default:l(()=>[B(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20G1%5B%22%E7%BB%84%20A%20%E5%BD%92%E7%BA%A6%E5%AE%8C%E6%88%90%22%5D%20--%3E%20R%5B%22%E6%A0%91%E6%A0%B9%E6%89%80%E5%9C%A8%E7%BB%84%20B%22%5D%0A%20%20G2%5B%22%E7%BB%84%20C%20%E5%BD%92%E7%BA%A6%E5%AE%8C%E6%88%90%22%5D%20--%3E%20R%0A%20%20R%20--%3E%20LB%5B%22%E5%A4%9A%E8%82%A1%E6%B5%81%E9%87%8F%E5%90%8C%E6%97%B6%E6%8C%A4%E5%8D%A0%E7%BB%84%E9%97%B4%E9%95%BF%E8%BE%B9%22%5D%0A%20%20LB%20--%3E%20HOT%5B%22incast%20%E7%83%AD%E7%82%B9%EF%BC%9A%E5%90%8C%E6%AD%A5%E6%B3%A2%E5%8D%A1%E6%AD%BB%22%5D%0A%20%20ALT%5B%22%E7%8E%AF%E9%9D%A2%EF%BC%9A%E6%B2%BF%E4%B8%80%E7%BB%B4%E5%81%9A%E7%8E%AF%E5%BD%92%E7%BA%A6%22%5D%20--%3E%20OK%5B%22%E6%B5%81%E9%87%8F%E7%95%99%E5%9C%A8%E7%BD%91%E6%A0%BC%E8%BE%B9%3Cbr%3E%E4%B8%8D%E7%A2%B0%E9%95%BF%E8%BE%B9%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">这张图回答「跨组集体为什么打爆 Dragonfly」：树根定在某个组后，所有其他组的归约结果在同一同步波里涌向它，长边成为必经瓶颈；环面把逻辑环嵌进物理环后流量只走网格边，天然避开这种汇聚点。</span></p><p><a href="/llm/collective-bandwidth-model">带宽模型</a> 里的 \\(\\beta\\) 在这三种图上都不是全局常数：脂肪树是分层 \\(\\beta\\)，Dragonfly 是组内/组间两档，环面是按跳数乘每跳 \\(\\beta\\)。套公式必须先问当前进程组的最远一对在哪一档。</p><p><span class="marginnote">超节点 NVLink 域在三种柜外拓扑里都可以当「组内」用。柜外选 Dragonfly 还是脂肪树，是直径、成本与集体热点之间的设施决策，不是模型超参。软件能做的是别把 EP 跨组。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 Blue Gene 时代的三维环面延迟数字抄到现代 GPU 以太网环面上。不要在厂商只提供脂肪树参考架构时，自己在图纸上画 Dragonfly 却按轨优化绑定进程。不要假设 NCCL 的 Ring 在环面一定最优——逻辑环与物理环未嵌入时，Ring 是最差之一。</p><p>TPU 的 torus / mesh 是加速器片间互连，与数据中心环面不是同一层；TPU 课再写片上 mesh。本课只对照<strong>主机侧 / 柜外</strong>网络。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>脂肪树扩端口；Dragonfly 用组间长边换直径；环面用规则邻居换可预测局部性。</li><li>集体的逻辑邻居必须嵌进物理局部：组内或一维环，而不是随机编号。</li><li>\\(\\beta\\) 分档：组内/组间、或按跳数；禁止用单一网卡标称套全集群。</li><li>All-to-All 打长边与打叶子上行同样致命，减压手段是缩进程组。</li><li>出处：Kim 等 Dragonfly；HPC 环面系统实践；GPU 侧仍以 NCCL 拓扑探测为准。</li></ul>',8))])}const y=i(d,[["render",p]]);export{h as __pageData,y as default};
